mapper.select:
select c.title as courseTitle, c.cover as courseCover, ch.sort as chapterSort, v.title as videoTitle, v.sort as videoSort, r.create_time as createTime, u.nickname as nickname from edu_course c , edu_chapter ch, edu_video v, edu_study_record r,acl_user u where c.id = r.course_id and ch.id = r.chapter_id and v.id = r.video_id and u.id = r.uid
and ${ew.sqlSegment}
order by r.create_time desc
